/*
 * A069755  Frobenius number of the numerical semigroup generated by 3
 *          consecutive triangular numbers.
 * https://oeis.org/A069755
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  easy, nice, nonn
 * Formula:   a(n) = (6*n³ + 18*n² + 12*n - 8)/8 for even n a(n) = (6*n³ +
 *            12*n² - 6*n - 20)/8 for odd n The sequence is defined for n ≥ 2;
 *            for indices below 2 the value is irrelevant and 0 is returned
 * Range:     u8 n <= 3, u16 n <= 21, u32 n <= 999, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* For n < 2 the sequence is not defined – return 0. */
    if (n < 2) {
        return 0;
    }

    /* Work entirely with seq_t to avoid intermediate overflow and
       to be compatible with arbitrary‑precision builds. */
    seq_t n_seq = (seq_t)n;
    seq_t n2    = n_seq * n_seq;         /* n²   */
    seq_t n3    = n2 * n_seq;             /* n³   */

    seq_t num;
    if ((n & 1) == 0) {                  /* even n  */
        num = 6 * n3 + 18 * n2 + 12 * n_seq - 8;
    } else {                             /* odd n   */
        num = 6 * n3 + 12 * n2 - 6 * n_seq - 20;
    }

    /* The numerator is always divisible by 8. */
    return num / 8;
}
